const traceSummary=(item)=>{if(item.kind==="message"){const unavailable=item.message.deleted?"Deleted message":list(item.message.attachments).length?"":"Message content unavailable";const content=item.summary?'<div class="trace-content">'+discordText(item.summary,item.message.mentions,item.message.roles)+'</div>':unavailable?'<div class="trace-content unavailable">'+unavailable+'</div>':"";return content+messageAttachments(item.message)}const metadata=traceMetadata(item.metadata);return (item.summary?'<span class="trace-summary">'+esc(item.summary)+'</span>':"")+(metadata.length?'<span class="trace-metadata">'+metadata.map((value)=>'<span>'+esc(value)+'</span>').join("")+'</span>':"")+(item.code?'<code>'+esc(item.code)+'</code>':"")+(item.count>1?'<small>Repeated '+esc(item.count)+' times from '+esc(traceTime(item.firstAt))+'</small>':"")};
const traceRow=(item)=>'<li class="trace-row '+esc(item.kind)+(item.message?.current?' current':'')+'">'+traceTimeCell(item)+'<span class="trace-marker story-status-indicator" data-state="'+esc(traceState(item))+'" role="img" aria-label="Status: '+esc(traceState(item))+'"></span><span class="trace-type">'+esc(traceType(item.type))+'</span><div class="trace-copy"><strong>'+esc(item.title)+(item.count>1?' <span>×'+esc(item.count)+'</span>':"")+'</strong>'+traceSummary(item)+'</div>'+(Number.isFinite(item.durationMs)?'<span class="trace-duration">'+esc(seconds(item.durationMs))+'</span>':'<span class="trace-duration"></span>')+'</li>';
const detailTrace=(story,detail)=>{const projected=traceItems(story,detail);if(!projected.items.length)return "";const visible=traceExpanded?projected.items:projected.items.filter((item)=>item.important);const canToggle=visible.length<projected.items.length||traceExpanded&&projected.items.some((item)=>!item.important);const summary=(traceExpanded?"All":"Highlights")+" · "+visible.length+" of "+projected.items.length+(projected.total===projected.items.length?"":" groups · "+projected.total+" records");return '<section class="detail-section trace-section"><div class="trace-heading"><div><h2>Trace</h2><span>'+esc(summary)+'</span></div>'+(canToggle?'<button id="trace-toggle" type="button" aria-expanded="'+String(traceExpanded)+'">'+(traceExpanded?'Show highlights':'Show all '+projected.items.length)+'</button>':"")+'</div><ol class="trace-list">'+visible.map(traceRow).join("")+'</ol></section>'};
