el("activity-type-trigger").addEventListener("keydown",(event)=>{if(!["ArrowDown","ArrowUp"].includes(event.key))return;event.preventDefault();openTypeMenu();const options=typeOptions();const selected=options.findIndex((option)=>activityTypes.has(option.dataset.activityType));options[event.key==="ArrowUp"?Math.max(0,selected):Math.min(options.length-1,selected+1)]?.focus()});
