const activityApiParams=(extra={})=>{const searching=Object.hasOwn(extra,"search");const params=new URLSearchParams({filter:searching?"all":activityFilter,types:extra.types||activityTypeKeys.filter((type)=>activityTypes.has(type)).join(","),limit:String(extra.limit||60)});if(extra.cursor)params.set("cursor",extra.cursor);if(searching)params.set("search",extra.search||"");if(extra.selectedKind)params.set("selectedKind",extra.selectedKind);if(extra.selectedId)params.set("selectedId",extra.selectedId);return params.toString()};
