async function refreshActivityDetail(route,force=false){const key=route.kind+":"+route.id;const version=activityDetailVersion(route);if(detailState.key===key&&detailState.loading)return;if(!force&&detailState.key===key&&detailState.data&&detailState.version===version)return;const changing=detailState.key!==key;const preserve=changing&&Boolean(detailState.data);if(changing){detailState={key,data:null,loading:false,error:null,version:null};traceExpanded=false}detailState.loading=true;const view=el("activity-detail-view");if(changing){document.body.classList.add("detail-selected");el("activity-back").href="/"+activityQuery()+"#activity-panel";view.setAttribute("aria-busy","true");view.classList.add("is-switching");view.classList.toggle("preserving-detail",preserve);if(!preserve)renderActivityDetail(null,route);if(latestSnapshot)renderActivity(latestSnapshot)}try{const data=await fetchJson("/api/activity/"+encodeURIComponent(route.kind)+"/"+encodeURIComponent(route.id),8000);if(detailState.key!==key)return;const changed=JSON.stringify(data)!==JSON.stringify(detailState.data);detailState.data=data;detailState.error=null;detailState.version=version;if(changing||changed)renderActivityDetail(data,route)}catch(error){if(detailState.key===key){detailState.error=error;detailState.data=null;renderActivityDetail(null,route)}}finally{if(detailState.key===key){detailState.loading=false;view.setAttribute("aria-busy","false");if(changing){view.scrollTo({top:0});requestAnimationFrame(()=>{if(detailState.key===key){view.classList.remove("is-switching","preserving-detail")}})}if(latestSnapshot)renderActivity(latestSnapshot)}}}
window.addEventListener("popstate",()=>{const route=activityRoute();if(route){refreshActivityDetail(route);if(mobileWorkspace())requestAnimationFrame(()=>el("activity-back").focus())}else{clearActivityDetail();focusActivityList()}});
async function refresh(){if(refreshInFlight)return refreshInFlight;refreshInFlight=(async()=>{await refreshSnapshot();const route=activityRoute();if(route){await ensureRouteStory(route);await refreshActivityDetail(route)}else clearActivityDetail()})().catch(()=>{if(latestSnapshot){staleState("Data stale · reconnecting automatically")}else{el("service-summary").textContent="Services unavailable";el("producer-summary").textContent="Producers unavailable";loadingError("dashboard-loading","Production data unavailable")}}).finally(()=>{refreshInFlight=null});return refreshInFlight}
refresh();setInterval(refresh,5000);
